const G = "6Crcx5cJrWQ6w4cG";
const N = "6gfWcx5q832xJ6XJ";
const eRegex = /^[\p{Emoji}\u2000-\u32FF]/u;
const matched = $input.all().filter(i => {
  const t = i.json;
  const pid = String(t.project_id);
  const matchProject = (pid === G || pid === N);
  const noEmoji = !eRegex.test(String(t.content || "").trim());
  return matchProject && noEmoji;
}).map(i => ({ json: { ...i.json, is_groceries: String(i.json.project_id) === G } }));

// LIMIT TO 2 ITEMS TO AVOID RATE LIMITS DURING BACKLOG PROCESSING
return matched.slice(0, 2);

const rawItems = $input.all().map(i => i.json);
let mappings;
if (rawItems.length === 1 && typeof rawItems[0].data === "string") {
  mappings = JSON.parse(rawItems[0].data);
} else if (rawItems.length === 1 && Array.isArray(rawItems[0].data)) {
  mappings = rawItems[0].data;
} else {
  mappings = rawItems;
}
mappings = mappings.filter(m => m.emoji && m.patterns);

const tasks = $("Identify Task").all().map(i => i.json);
const groceryTasks = tasks.filter(t => t.is_groceries === true);

return groceryTasks.map(t => {
  let matched = false;
  for (const m of mappings) {
    const regex = new RegExp("^\\s*(" + m.patterns.join("|") + ")", "i");
    if (regex.test(t.content)) {
      t.content = `${m.emoji} ${t.content}`;
      matched = true;
      break;
    }
  }
  return { json: { ...t, is_matched: matched ? "yes" : "no" } };
});

const items = $input.all();
const candidates = $('Switch 1').all();
const fallbackTasks = $('Identify Task').all();

return items.flatMap(item => {
  const outputs = item.json.output || [item.json];
  return outputs.map((out, index) => {
    const match = candidates.find(c =>
      out.id && String(c.json.id) === String(out.id)
    );
    const source = match || candidates[index] || fallbackTasks[index];
    return {
      json: {
        id: out.id || source?.json?.id,
        content: out.content,
      },
    };
  });
});

const res = $input.item.json;
const results = res.results || [];
const first = results.find(r => r.img_src || r.thumbnail_src);
if (!first) return null;
const imageUrl = first.img_src || first.thumbnail_src;

const extMatch = imageUrl.split('?')[0].match(/\.([a-zA-Z0-9]+)$/);
const ext = (extMatch ? extMatch[1] : 'jpg').toLowerCase();
const mimeByExt = { jpg: 'image/jpeg', jpeg: 'image/jpeg', png: 'image/png', webp: 'image/webp', gif: 'image/gif' };
const fileType = mimeByExt[ext] || 'image/jpeg';
const fileName = `product.${ext === 'jpeg' ? 'jpg' : ext}`;

return { json: { id: $('Prepare Image Query').item.json.id, imageUrl, fileName, fileType } };

const res = $input.item.json;
const hasPhoto = (res.results || []).some(c => c.file_attachment?.resource_type === 'image');
if (hasPhoto) return null;
const source = $('Limit Photo Checks').item.json;
return { json: { id: source.id, content: source.content } };

const res = $input.item.json;
const hasPhoto = (res.results || []).some(c => c.file_attachment?.resource_type === 'image');
if (hasPhoto) return null;
const source = $('Extract Image URL').item.json;
return { json: source };

